    halo.addColorStop(.56, color(hue, 67, 48, .095));
    halo.addColorStop(1, color(hue, 65, 43, 0));
    g.clearRect(0, 0, 160, 160);
    g.fillStyle = halo;
    g.fillRect(0, 0, 160, 160);

